package org.brightstats.data;
import java.util.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.security.*;import com.google.gson.*;import org.brightstats.stats.*;
/** Cluster labels are bound to original source rows, before replacement or selection. */
public final class ClusterData {
 private ClusterData(){}
 public record Provenance(String clusterColumn,int suppliedRows,int excludedRows,List<Integer> sourceRows,String selectedDataSha256){public Provenance{sourceRows=List.copyOf(sourceRows);}}
 public record Selected(double[][] data,List<String> ids,Provenance provenance){public Selected{data=Matrices.copy(data);ids=List.copyOf(ids);}@Override public double[][] data(){return Matrices.copy(data);}}
 public static List<String> sourceColumns(JsonObject history,List<String> names){return history==null?List.copyOf(names):ImportHistory.read(history).raw().headers();}
 public static Selected select(JsonObject history,List<String> names,double[][] prepared,int clusterColumn,String binding,SemModel.Model model,boolean completeCases){
  List<String> headers=sourceColumns(history,names);if(clusterColumn<0||clusterColumn>=headers.size()||!headers.get(clusterColumn).equals(binding))throw new IllegalArgumentException("Cluster source-column binding changed; configure the analysis again.");
  double[][] raw=MissingInput.originalAll(history,names,prepared);List<String> labels=new ArrayList<>();if(history!=null){var original=ImportHistory.read(history);for(var row:original.raw().rows()){String cell=row.get(clusterColumn);labels.add(DataPreparation.missing(cell,original.settings())?"":cell.strip());}}else for(var row:raw)labels.add(Double.isFinite(row[clusterColumn])?Double.toString(row[clusterColumn]):"");
  int[] observed=model.observed(),columns=new int[observed.length];for(int j=0;j<columns.length;j++){String name=model.variables().get(observed[j]);columns[j]=names.indexOf(name);if(columns[j]<0||name.equals(binding))throw new IllegalArgumentException("Observed variables must be available numeric columns separate from the cluster ID.");}
  List<double[]> selected=new ArrayList<>();List<String> ids=new ArrayList<>();List<Integer> sourceRows=new ArrayList<>();for(int i=0;i<raw.length;i++){boolean finite=true;double[] row=new double[columns.length];for(int j=0;j<columns.length;j++){row[j]=raw[i][columns[j]];finite&=Double.isFinite(row[j]);}if(completeCases&&(!finite||labels.get(i).isBlank()))continue;if(labels.get(i).isBlank())throw new IllegalArgumentException("A source row has a missing cluster ID; supply it or explicitly select complete cases.");selected.add(row);ids.add(labels.get(i));sourceRows.add(i+1);}
  double[][] data=selected.toArray(double[][]::new);try{MessageDigest digest=MessageDigest.getInstance("SHA-256");digest.update("brightstats-cluster-source-v1".getBytes(StandardCharsets.UTF_8));digest.update(ByteBuffer.allocate(4).putInt(observed.length).array());for(int observedIndex:observed)text(digest,model.variables().get(observedIndex));digest.update(ByteBuffer.allocate(4).putInt(data.length).array());for(int i=0;i<data.length;i++){digest.update(ByteBuffer.allocate(4).putInt(sourceRows.get(i)).array());text(digest,ids.get(i));for(double value:data[i])digest.update(ByteBuffer.allocate(8).putLong(Double.doubleToLongBits(value)).array());}return new Selected(data,ids,new Provenance(binding,raw.length,raw.length-data.length,sourceRows,HexFormat.of().formatHex(digest.digest())));}catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
 }
 private static void text(MessageDigest digest,String value){byte[] encoded=value.getBytes(StandardCharsets.UTF_8);digest.update(ByteBuffer.allocate(4).putInt(encoded.length).array());digest.update(encoded);}
}
